export default function GeneratedComponent() {
  // BUDGET height: header 2.25 + titlestrip 2 + main(jog/fader) 17 + transport 2.5 + pads 3.5 + loop 2 + footer 1.75 + gaps 1.5 = 32.5 ≤ 38.1
  // BUDGET width: jog 17 + gap 0.75 + readouts 9 + gap 0.75 + fader col 4.5 + padding 1.5 = 33.5 ≤ 48.6

  const DUR = 372;
  const BASE_BPM = 128;

  const [playing, setPlaying] = useState(false);
  const [time, setTime] = useState(0);
  const [rot, setRot] = useState(0);
  const [pitch, setPitch] = useState(0);
  const [keylock, setKeylock] = useState(true);
  const [sync, setSync] = useState(false);
  const [loopOn, setLoopOn] = useState(false);
  const [loopLen, setLoopLen] = useState("4");
  const [scrubbing, setScrubbing] = useState(false);
  const [activeCue, setActiveCue] = useState<number | null>(null);
  const [cues, setCues] = useState<(number | null)[]>([0, 32.5, 96.25, null]);
  const cueRef = useRef(0);

  const rate = 1 + pitch / 100;
  const bpm = BASE_BPM * rate;

  useEffect(() => {
    if (!playing || scrubbing) return;
    const id = setInterval(() => {
      const d = 0.05 * rate;
      setTime((t) => (t + d) % DUR);
      setRot((r) => r + d / 1.8);
    }, 50);
    return () => clearInterval(id);
  }, [playing, scrubbing, rate]);

  const fmt = (s: number) => {
    const v = Math.max(0, s);
    const m = Math.floor(v / 60);
    const sec = Math.floor(v % 60);
    return m + ":" + (sec < 10 ? "0" : "") + sec;
  };

  const scrub = useCallback((d: number) => {
    setRot((r) => r + d);
    setTime((t) => Math.min(DUR, Math.max(0, t + d * 1.8)));
  }, []);

  const hitCue = (i: number) => {
    setCues((c) => {
      if (c[i] == null) {
        const n = [...c];
        n[i] = time;
        return n;
      }
      return c;
    });
    const target = cues[i];
    if (target != null) setTime(target);
    setActiveCue(i);
    setTimeout(() => setActiveCue((a) => (a === i ? null : a)), 220);
  };

  const beats = [
    { id: "0.25", label: "1/4" },
    { id: "1", label: "1" },
    { id: "4", label: "4" },
    { id: "8", label: "8" },
  ];

  const prog = time / DUR;

  return (
    <div className="h-full w-full flex flex-col overflow-hidden rounded-none bg-gradient-to-br from-[#0a0612] via-[#120a1f] to-[#050308] text-zinc-100">
      {/* header */}
      <div className="h-9 flex-none flex items-center justify-between px-3 bg-gradient-to-r from-zinc-900 to-zinc-950 border-b border-violet-500/25">
        <div className="flex items-center gap-2 min-w-0">
          <span className="w-2 h-2 rounded-full bg-cyan-400 text-cyan-400 shadow-[0_0_8px_currentColor] animate-pulse" />
          <span className="text-sm font-bold tracking-[0.18em] uppercase text-zinc-200 truncate">Deck A</span>
        </div>
        <div className="flex items-center gap-2">
          <Indicator active={playing} tone="accent" blink={playing} />
          <span className="text-[10px] font-mono uppercase tracking-[0.14em] text-zinc-500 truncate">
            {playing ? "playing" : "standby"}
          </span>
        </div>
      </div>

      {/* body */}
      <div className="flex-1 flex flex-col gap-2 p-2 min-h-0 overflow-y-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
        {/* track title */}
        <div className="flex-none h-[2rem] flex items-stretch gap-2">
          <div className="flex-1 h-[2rem]">
            <Readout value="NIGHTDRIVE ▸ VELVET AXIS" marquee />
          </div>
          <div className="w-[7rem] h-[2rem]">
            <Readout value={bpm} unit="BPM" decimals={1} />
          </div>
        </div>

        {/* main row */}
        <div className="flex-1 flex items-stretch gap-2">
          {/* jog + transport */}
          <div className="flex-1 flex flex-col gap-2">
            <div className="flex-1 flex items-center justify-center relative">
              <div
                className="absolute inset-0 rounded-full blur-2xl transition-opacity duration-500"
                style={{
                  opacity: playing ? 0.35 : 0.1,
                  background:
                    "radial-gradient(circle at 50% 50%, rgba(34,211,238,0.5), transparent 62%)",
                }}
              />
              <div className="h-full aspect-square relative">
                <JogWheel
                  rotation={rot}
                  spinning={playing}
                  onScrub={scrub}
                  onTouchChange={setScrubbing}
                />
              </div>
            </div>
            <div className="flex-none h-[2.5rem] flex items-stretch gap-2">
              <div className="w-[5rem] h-[2.5rem]">
                <PushButton mode="momentary" tone="neutral" onPress={() => { setTime(cueRef.current); setPlaying(false); }}>
                  <span className="font-bold uppercase tracking-[0.12em]">CUE</span>
                </PushButton>
              </div>
              <div className="flex-1 h-[2.5rem]">
                <PushButton mode="toggle" tone="accent" on={playing} onChange={setPlaying}>
                  <span className="flex flex-col items-center leading-none">
                    <span className="font-bold uppercase tracking-[0.12em]">{playing ? "PAUSE" : "PLAY"}</span>
                    <span className="text-[0.6em] tracking-[0.2em] opacity-70">DECK A</span>
                  </span>
                </PushButton>
              </div>
              <div className="w-[5rem] h-[2.5rem]">
                <PushButton mode="toggle" tone="accent" on={sync} onChange={setSync}>
                  <span className="font-bold uppercase tracking-[0.12em]">SYNC</span>
                </PushButton>
              </div>
            </div>
          </div>

          {/* time + pitch column */}
          <div className="w-[13rem] flex items-stretch gap-2">
            <div className="flex-1 flex flex-col gap-2">
              <div className="h-[2rem]">
                <Readout value={fmt(time)} unit="ELAP" />
              </div>
              <div className="h-[2rem]">
                <Readout value={"-" + fmt(DUR - time)} unit="REM" />
              </div>
              <div className="flex-1 rounded-xl border border-zinc-800/80 bg-[#08060f] shadow-[inset_0_2px_10px_rgba(0,0,0,0.8)] p-2 flex flex-col justify-between">
                <div className="flex items-center justify-between gap-2">
                  <span className="text-[11px] font-semibold tracking-[0.14em] uppercase text-zinc-500 truncate">Keylock</span>
                  <div className="w-[3.25rem] h-[1.75rem]">
                    <ToggleSwitch on={keylock} onChange={setKeylock} />
                  </div>
                </div>
                <div className="relative h-[0.4rem] rounded-full bg-zinc-900 border border-zinc-800 overflow-clip">
                  <div
                    className="absolute inset-y-0 left-0 bg-gradient-to-r from-cyan-500 to-violet-500 transition-all duration-75 ease-linear"
                    style={{ width: (prog * 100).toFixed(2) + "%" }}
                  />
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-[10px] font-mono uppercase tracking-[0.14em] text-zinc-600">PITCH</span>
                  <span className="font-mono font-bold tracking-tight text-cyan-300 drop-shadow-[0_0_6px_currentColor] text-sm">
                    {(pitch >= 0 ? "+" : "") + pitch.toFixed(1)}%
                  </span>
                </div>
              </div>
            </div>
            <div className="w-[3.25rem] flex flex-col items-center gap-1">
              <div className="w-[3.25rem] flex-1">
                <Fader
                  min={-8}
                  max={8}
                  value={pitch}
                  onChange={setPitch}
                  orientation="vertical"
                  bipolar
                  detents={[-8, -4, 0, 4, 8]}
                />
              </div>
              <span className="flex-none text-[10px] font-semibold tracking-[0.14em] uppercase text-zinc-500">PITCH</span>
            </div>
          </div>
        </div>

        {/* hot cues + loop */}
        <div className="flex-none flex items-stretch gap-2">
          <div className="flex gap-2">
            {[0, 1, 2, 3].map((i) => (
              <div key={"cue-" + i} className="w-[3.25rem] h-[3.25rem]">
                <CuePad
                  onPress={() => hitCue(i)}
                  onLongPress={() => setCues((c) => { const n = [...c]; n[i] = null; return n; })}
                  assigned={cues[i] != null}
                  active={activeCue === i}
                >
                  <span className="flex flex-col items-center leading-none">
                    <span className="font-bold">{i + 1}</span>
                    <span className="text-[0.55em] tracking-[0.2em] opacity-70">
                      {cues[i] != null ? fmt(cues[i] as number) : "SET"}
                    </span>
                  </span>
                </CuePad>
              </div>
            ))}
          </div>
          <div className="flex-1 flex items-stretch gap-2 rounded-xl border border-zinc-800/80 bg-[#08060f] shadow-[inset_0_2px_10px_rgba(0,0,0,0.8)] p-2">
            <div className="w-[4.5rem] h-[2.25rem]">
              <PushButton mode="toggle" tone="accent" on={loopOn} onChange={setLoopOn}>
                <span className="font-bold uppercase tracking-[0.12em]">LOOP</span>
              </PushButton>
            </div>
            <div className="flex-1 h-[2.25rem]">
              <SegmentedSelector options={beats} value={loopLen} onChange={setLoopLen} />
            </div>
            <div className="w-[5.5rem] h-[2.25rem]">
              <Readout value={loopLen} unit="BEATS" />
            </div>
          </div>
        </div>
      </div>

      {/* footer */}
      <div className="h-7 flex-none flex items-center justify-between px-3 bg-zinc-950/90 border-t border-zinc-800/80">
        <span className="text-[10px] font-mono uppercase tracking-[0.14em] text-zinc-500 truncate">
          CH-A · {keylock ? "KEYLOCK ON" : "KEYLOCK OFF"} · {sync ? "SYNCED" : "FREE"}
        </span>
        <span className="text-[10px] font-mono uppercase tracking-[0.14em] text-cyan-300/80 truncate">
          {loopOn ? "LOOP " + loopLen + "B ACTIVE" : "LOOP IDLE"}
        </span>
      </div>
    </div>
  );
}

export default function GeneratedComponent() {
  // BUDGET height: header 2.25 + pad 1.5 + readouts 2.75 + gap 0.5 + main (jog 21 + gap 0.5 + transport 3 = 24.5) + footer 1.75 = 32.75 ≤ 38.1
  // BUDGET width: pad 1.5 + jog 21 + gap 0.75 + fader col 4 + gap 0.75 + right col 15.5 + pad 1.5 = 45 ≤ 48.6

  const TRACK = { title: "MIDNIGHT VOLTAGE — KAORI B.", baseBpm: 128.0, duration: 312 };

  const [playing, setPlaying] = useState(false);
  const [pos, setPos] = useState(0);
  const [rot, setRot] = useState(0);
  const [pitch, setPitch] = useState(0);
  const [keylock, setKeylock] = useState(true);
  const [sync, setSync] = useState(false);
  const [loopOn, setLoopOn] = useState(false);
  const [loopBeats, setLoopBeats] = useState("4");
  const [cueTime, setCueTime] = useState(0);
  const [activeCue, setActiveCue] = useState<number | null>(null);
  const [touching, setTouching] = useState(false);

  const cues = useMemo(
    () => [
      { id: 0, label: "INTRO", t: 0, assigned: true },
      { id: 1, label: "DROP", t: 64, assigned: true },
      { id: 2, label: "BRK", t: 148, assigned: true },
      { id: 3, label: "OUT", t: 0, assigned: false },
    ],
    []
  );

  const rate = 1 + pitch / 100;
  const bpm = TRACK.baseBpm * rate;

  useEffect(() => {
    if (!playing || touching) return;
    const id = setInterval(() => {
      setPos((p) => {
        const n = p + 0.1 * rate;
        return n >= TRACK.duration ? TRACK.duration : n;
      });
      setRot((r) => r + 0.1 * rate * 0.5555);
    }, 100);
    return () => clearInterval(id);
  }, [playing, rate, touching]);

  const fmt = (s: number) => {
    const v = Math.max(0, s);
    const m = Math.floor(v / 60);
    const sec = Math.floor(v % 60);
    return m + ":" + (sec < 10 ? "0" + sec : sec);
  };

  const scrub = useCallback((d: number) => {
    setRot((r) => r + d);
    setPos((p) => Math.min(TRACK.duration, Math.max(0, p + d * 1.8)));
  }, []);

  return (
    <div className="h-full w-full flex flex-col overflow-hidden rounded-none bg-gradient-to-br from-[#0a0612] via-[#120a1f] to-[#050308] text-zinc-100 font-sans">
      {/* HEADER */}
      <div className="h-9 flex-none flex items-center gap-2 px-3 bg-gradient-to-r from-zinc-900 to-zinc-950 border-b border-violet-500/25">
        <span className="h-2 w-2 rounded-full bg-amber-400 shadow-[0_0_8px_currentColor] text-amber-400" />
        <span className="text-sm font-bold tracking-[0.18em] uppercase text-zinc-200 truncate">Deck B</span>
        <span className="ml-auto flex items-center gap-2">
          <Indicator active={playing} tone="accent" blink={false} />
          <span className="text-[10px] font-medium tracking-wide uppercase text-zinc-600">
            {playing ? "PLAYING" : "PAUSED"}
          </span>
        </span>
      </div>

      {/* BODY */}
      <div className="flex-1 flex flex-col gap-2 p-3 min-h-0 overflow-y-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
        {/* READOUT STRIP */}
        <div className="flex-none flex items-stretch gap-2 h-[2.75rem]">
          <div className="flex-1">
            <Readout value={TRACK.title} marquee />
          </div>
          <div className="w-[7rem]">
            <Readout value={bpm} unit="BPM" decimals={2} />
          </div>
          <div className="w-[5.5rem]">
            <Readout value={fmt(pos)} />
          </div>
          <div className="w-[5.5rem]">
            <Readout value={"-" + fmt(TRACK.duration - pos)} />
          </div>
        </div>

        {/* MAIN */}
        <div className="flex-1 flex items-stretch gap-3">
          {/* LEFT: PLATTER + TRANSPORT */}
          <div className="flex flex-col gap-2">
            <div className="w-[21rem] h-[21rem]">
              <JogWheel
                rotation={rot}
                spinning={playing && !touching}
                onScrub={scrub}
                onTouchChange={setTouching}
              />
            </div>
            <div className="flex gap-2 h-[3.25rem]">
              <div className="w-[7rem]">
                <PushButton
                  mode="momentary"
                  tone="neutral"
                  onPress={() => {
                    setPos(cueTime);
                    setPlaying(false);
                    setActiveCue(null);
                  }}
                >
                  <span className="font-bold uppercase tracking-[0.12em]">CUE</span>
                </PushButton>
              </div>
              <div className="flex-1">
                <PushButton mode="toggle" tone="accent" on={playing} onChange={setPlaying}>
                  <span className="flex flex-col items-center leading-none">
                    <span className="font-bold uppercase tracking-[0.12em]">
                      {playing ? "PAUSE" : "PLAY"}
                    </span>
                    <span className="text-[0.62em] tracking-[0.2em] opacity-70">DECK B</span>
                  </span>
                </PushButton>
              </div>
              <div className="w-[6rem]">
                <PushButton
                  mode="toggle"
                  tone="accent"
                  on={sync}
                  onChange={(v) => {
                    setSync(v);
                    if (v) setPitch(0);
                  }}
                >
                  <span className="font-bold uppercase tracking-[0.12em]">SYNC</span>
                </PushButton>
              </div>
            </div>
          </div>

          {/* PITCH FADER COLUMN */}
          <div className="flex flex-col items-center gap-1 w-[4rem]">
            <span className="text-[11px] font-semibold tracking-[0.14em] uppercase text-zinc-500">PITCH</span>
            <div className="flex-1 w-[3rem]">
              <Fader
                min={-8}
                max={8}
                value={pitch}
                onChange={(v) => {
                  setPitch(v);
                  setSync(false);
                }}
                orientation="vertical"
                bipolar
                detents={[0]}
              />
            </div>
            <span className="text-[10px] font-mono font-bold tracking-tight text-amber-300 drop-shadow-[0_0_6px_currentColor]">
              {(pitch >= 0 ? "+" : "") + pitch.toFixed(1) + "%"}
            </span>
          </div>

          {/* RIGHT COLUMN */}
          <div className="flex-1 flex flex-col gap-2">
            {/* HOT CUES */}
            <div className="flex flex-col gap-1">
              <span className="text-[11px] font-semibold tracking-[0.14em] uppercase text-zinc-500">Hot Cues</span>
              <div className="grid grid-cols-2 gap-2">
                {cues.map((c) => (
                  <div key={"cue-" + c.id} className="h-[4.5rem]">
                    <CuePad
                      assigned={c.assigned}
                      active={activeCue === c.id}
                      onPress={() => {
                        if (!c.assigned) return;
                        setActiveCue(c.id);
                        setPos(c.t);
                      }}
                      onLongPress={() => {
                        setCueTime(pos);
                        setActiveCue(c.id);
                      }}
                    >
                      <span className="flex flex-col items-center leading-none">
                        <span className="font-bold uppercase tracking-[0.14em]">{c.label}</span>
                        <span className="text-[0.62em] font-mono opacity-70">{fmt(c.t)}</span>
                      </span>
                    </CuePad>
                  </div>
                ))}
              </div>
            </div>

            {/* LOOP */}
            <div className="flex flex-col gap-1">
              <span className="text-[11px] font-semibold tracking-[0.14em] uppercase text-zinc-500">Loop</span>
              <div className="h-[2rem]">
                <SegmentedSelector
                  options={[
                    { id: "1", label: "1" },
                    { id: "2", label: "2" },
                    { id: "4", label: "4" },
                    { id: "8", label: "8" },
                    { id: "16", label: "16" },
                  ]}
                  value={loopBeats}
                  onChange={setLoopBeats}
                  orientation="horizontal"
                />
              </div>
              <div className="flex gap-2 h-[2.5rem]">
                <div className="flex-1">
                  <PushButton mode="toggle" tone="accent" on={loopOn} onChange={setLoopOn}>
                    <span className="font-bold uppercase tracking-[0.12em]">
                      {loopOn ? "EXIT" : "LOOP"}
                    </span>
                  </PushButton>
                </div>
                <div className="w-[6.5rem]">
                  <Readout value={loopBeats + " BEAT"} />
                </div>
              </div>
            </div>

            {/* KEYLOCK */}
            <div className="mt-auto flex items-center justify-between gap-2 h-[2.25rem] px-2 rounded-xl bg-[#08060f] border border-zinc-800/80 shadow-[inset_0_2px_10px_rgba(0,0,0,0.8)]">
              <span className="text-[11px] font-semibold tracking-[0.14em] uppercase text-zinc-500 truncate">
                Keylock
              </span>
              <div className="w-[3.5rem] h-[1.75rem]">
                <ToggleSwitch on={keylock} onChange={setKeylock} />
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* FOOTER */}
      <div className="h-7 flex-none flex items-center justify-between px-3 bg-zinc-950/90 border-t border-zinc-800/80 text-[10px] font-mono uppercase tracking-[0.14em] text-zinc-500">
        <span className="truncate">CH-B · {keylock ? "KEYLOCK ON" : "KEYLOCK OFF"}</span>
        <span className="truncate">{sync ? "SYNC LOCKED" : "PITCH " + (pitch >= 0 ? "+" : "") + pitch.toFixed(1) + "%"}</span>
      </div>
    </div>
  );
}

export default function GeneratedComponent() {
  // BUDGET height: header 2.25 + pad 0.75 + laneA 5.5 + gap 0.5 + laneB 5.5 + pad 0.75 = 15.25 ≤ 17.3
  // BUDGET width: pad 0.75 + lanes(flex ~140) + gap 0.75 + zoom col 8 + pad 0.75 = 156.1 ≤ 156.1

  const makeWave = (seed: number, len: number) => {
    const out: number[] = [];
    let s = seed;
    for (let i = 0; i < len; i++) {
      s = (s * 9301 + 49297) % 233280;
      const r = s / 233280;
      const env = 0.45 + 0.4 * Math.sin(i / 90 + seed) + 0.15 * Math.sin(i / 17);
      const kick = i % 32 < 3 ? 0.35 : 0;
      out.push(Math.max(0.05, Math.min(1, env * (0.55 + r * 0.5) + kick)));
    }
    return out;
  };

  const waveA = useMemo(() => makeWave(7, 900), []);
  const waveB = useMemo(() => makeWave(41, 900), []);

  const durA = 312;
  const durB = 288;
  const bpmA = 126;
  const bpmB = 124;

  const gridA = useMemo(() => {
    const g: number[] = [];
    for (let t = 0.35; t < durA; t += 60 / bpmA) g.push(t);
    return g;
  }, []);
  const gridB = useMemo(() => {
    const g: number[] = [];
    for (let t = 1.1; t < durB; t += 60 / bpmB) g.push(t);
    return g;
  }, []);

  const [posA, setPosA] = useState(74.2);
  const [posB, setPosB] = useState(51.6);
  const [playA] = useState(true);
  const [playB] = useState(true);
  const [zoom, setZoom] = useState(4);

  useEffect(() => {
    const id = setInterval(() => {
      setPosA((p) => (playA ? (p + 0.1) % durA : p));
      setPosB((p) => (playB ? (p + 0.1) % durB : p));
    }, 100);
    return () => clearInterval(id);
  }, [playA, playB]);

  const fmt = (t: number) => {
    const m = Math.floor(t / 60);
    const s = Math.floor(t % 60);
    return m + ":" + (s < 10 ? "0" + s : s);
  };

  const drift = ((posA % (60 / bpmA)) - (posB % (60 / bpmB))) * 1000;

  const Lane = (props: {
    label: string;
    accent: string;
    dot: string;
    data: number[];
    duration: number;
    playhead: number;
    grid: number[];
    overlay?: number[];
    playing: boolean;
    bpm: number;
    onSeek: (t: number) => void;
  }) => (
    <div className="flex-1 flex items-stretch gap-2">
      <div className="w-[7.5rem] flex flex-col justify-center gap-1 px-2 rounded-xl bg-gradient-to-b from-zinc-900/95 to-zinc-950/95 border border-violet-500/25">
        <div className="flex items-center gap-1.5">
          <span className={"h-1.5 w-1.5 rounded-full " + props.dot + " shadow-[0_0_8px_currentColor]"} />
          <span className="text-[11px] font-semibold tracking-[0.14em] uppercase leading-none text-zinc-500 truncate">
            {props.label}
          </span>
        </div>
        <div className={"font-mono font-bold tracking-tight text-lg leading-none drop-shadow-[0_0_6px_currentColor] " + props.accent}>
          {props.bpm.toFixed(1)}
        </div>
        <div className="text-[10px] font-mono uppercase tracking-[0.14em] text-zinc-600">
          {fmt(props.playhead)} / {fmt(props.duration)}
        </div>
      </div>
      <div className="flex-1 rounded-xl border border-zinc-800/80 bg-[#08060f] shadow-[inset_0_2px_10px_rgba(0,0,0,0.8)] overflow-clip">
        <WaveformLane
          data={props.data}
          duration={props.duration}
          playhead={props.playhead}
          zoom={zoom}
          playing={props.playing}
          beatGrid={props.grid}
          overlayBeatGrid={props.overlay}
          onSeek={props.onSeek}
        />
      </div>
    </div>
